#!/usr/bin/env node
// Validate an ADR drafted by the architecture-review skill against docs/adr/0000-template.md,
// and optionally grade it against a golden case from skills/architecture-review/tests/cases.json.
//
// Usage:
//   node validate-adr.mjs <adr.md> [--repo <dir>] [--bench <dir>] [--status proposed] [--template-only] [--case <cases.json>#<id>] [--json]
//     --repo           every backticked repo path:line must exist under <dir> (the AI-SDLC-frappe root), line within the file
//     --bench          every backticked apps/... path:line (Frappe source) must exist under this bench directory
//     --status         require this exact status (the skill always writes "proposed")
//     --template-only  only check template conformance (no Risks table required); use for human-written ADRs
//     --case           also check the case's mustCite / mustMention / minOptions / minRisks
// Exit codes: 0 valid, 1 invalid or case failed, 2 usage error. Zero dependencies, Node 22.
import { readFileSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const SECTIONS = ["Context", "Options considered", "Decision", "Consequences", "Verification"];
export const OPTION_COLUMNS = ["option", "pros", "cons", "risk"];
export const RISK_COLUMNS = ["id", "severity", "category", "location", "evidence", "recommendation"];
export const SEVERITIES = ["critical", "high", "medium", "low", "info"];
const PATH_LINE = /`((?:[\w.-]+\/)*[\w.-]+\.(?:py|json|md|txt|mjs|ya?ml|toml)):(\d+)(?:-(\d+))?`/g;

export function splitRow(line) {
  const out = [];
  let cur = "";
  const body = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  for (let i = 0; i < body.length; i++) {
    if (body[i] === "\\" && body[i + 1] === "|") { cur += "|"; i++; continue; }
    if (body[i] === "|") { out.push(cur.trim()); cur = ""; continue; }
    cur += body[i];
  }
  out.push(cur.trim());
  return out;
}

function tables(text) {
  const result = [];
  let block = [];
  for (const line of [...text.split("\n"), ""]) {
    if (line.trim().startsWith("|")) block.push(line);
    else if (block.length) { result.push(block); block = []; }
  }
  return result.filter((b) => b.length >= 2).map((b) => ({
    header: splitRow(b[0]).map((c) => c.toLowerCase()),
    rows: b.slice(2).map(splitRow),
  }));
}

export function parseAdr(md) {
  const lines = md.split(/\r?\n/);
  const h2 = [];
  const body = new Map();
  let cur = null;
  for (const line of lines) {
    const m = /^## (?!#)(.+?)\s*$/.exec(line);
    if (m) { cur = m[1]; h2.push(cur); body.set(cur, []); continue; }
    if (cur) body.get(cur).push(line);
  }
  const text = new Map([...body].map(([k, v]) => [k, v.join("\n")]));
  const sub = (section, heading) => {
    const t = text.get(section) || "";
    const idx = t.search(new RegExp(`^### ${heading}\\s*$`, "m"));
    if (idx < 0) return null;
    const rest = t.slice(idx).split("\n").slice(1).join("\n");
    const next = rest.search(/^### /m);
    return next < 0 ? rest : rest.slice(0, next);
  };
  return { lines, h2, text, sub };
}

export function validateAdr(md, { repo = null, bench = null, status = null, templateOnly = false } = {}) {
  const errors = [];
  const { lines, h2, text, sub } = parseAdr(md);
  const title = /^# ADR-(\d{4}): (.+)$/.exec(lines[0] || "");
  if (!title) errors.push('first line must be "# ADR-NNNN: Title"');
  const meta = (key) => (lines.find((l) => l.startsWith(`- ${key}:`)) || "").slice(key.length + 3).trim();
  const st = meta("Status");
  if (!/^(proposed|accepted|superseded by ADR-\d{4})$/.test(st)) errors.push(`Status must be proposed | accepted | superseded by ADR-XXXX, got "${st}"`);
  if (status && st !== status) errors.push(`Status must be "${status}", got "${st}"`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(meta("Date"))) errors.push(`Date must be YYYY-MM-DD, got "${meta("Date")}"`);
  if (!meta("Deciders")) errors.push("Deciders line missing or empty");

  if (h2.join("|") !== SECTIONS.join("|")) errors.push(`H2 sections must be exactly, in order: ${SECTIONS.join(", ")} (got: ${h2.join(", ")})`);
  for (const s of SECTIONS) if (!(text.get(s) || "").trim()) errors.push(`section "${s}" is empty`);

  const opt = tables(text.get("Options considered") || "")[0];
  let optionCount = 0;
  if (!opt || opt.header.join("|") !== OPTION_COLUMNS.join("|")) errors.push("Options considered needs a table with columns Option | Pros | Cons | Risk");
  else {
    optionCount = opt.rows.length;
    if (optionCount < 2) errors.push(`Options considered needs at least 2 options, got ${optionCount}`);
    opt.rows.forEach((r, i) => { if (r.length !== 4 || r.some((c) => !c)) errors.push(`option row ${i + 1} must fill all 4 cells`); });
  }

  let riskCount = 0;
  if (!templateOnly) {
    const risks = sub("Consequences", "Risks");
    const t = risks ? tables(risks)[0] : null;
    if (!t) errors.push('Consequences needs a "### Risks" table');
    else if (t.header.join("|") !== RISK_COLUMNS.join("|")) errors.push(`Risks table columns must be: ${RISK_COLUMNS.join(" | ")}`);
    else {
      riskCount = t.rows.length;
      if (!riskCount) errors.push("Risks table has no rows");
      t.rows.forEach((r, i) => {
        if (!/^AR-\d{3}$/.test(r[0])) errors.push(`risk row ${i + 1}: id "${r[0]}" must be AR-NNN`);
        if (!SEVERITIES.includes(r[1])) errors.push(`risk row ${i + 1}: severity "${r[1]}" not in ${SEVERITIES.join("|")}`);
        if (!/^`[^`]+:\d+/.test(r[3] || "")) errors.push(`risk row ${i + 1}: location must be a backticked path:line`);
        if (!/`[^`]+`/.test(r[4] || "")) errors.push(`risk row ${i + 1}: evidence must quote code in backticks`);
      });
    }
    if (!sub("Context", "Current architecture \\(evidence\\)")) errors.push('Context needs a "### Current architecture (evidence)" sub-section');
    if (!/\btest_\w+/.test(text.get("Verification") || "")) errors.push("Verification must name concrete tests (test_... methods)");
  }

  const cites = [...md.matchAll(PATH_LINE)].map((m) => ({ path: m[1], from: Number(m[2]), to: Number(m[3] || m[2]) }));
  if (!templateOnly && cites.length < 3) errors.push(`expected at least 3 backticked path:line citations, got ${cites.length}`);
  for (const c of cites) {
    const fromBench = c.path.startsWith("apps/");
    const base = fromBench ? bench : repo;
    if (base) {
      const file = join(base, c.path);
      if (!existsSync(file)) { errors.push(`cited file not found under ${fromBench ? "--bench" : "--repo"}: ${c.path}`); continue; }
      const n = readFileSync(file, "utf8").split("\n").length;
      if (c.to > n || c.from > c.to) errors.push(`cited line ${c.path}:${c.from}${c.to !== c.from ? `-${c.to}` : ""} is outside the file (${n} lines)`);
    }
  }
  return { ok: errors.length === 0, errors, number: title ? title[1] : null, status: st, optionCount, riskCount, cites };
}

export function gradeCase(md, result, testCase) {
  const errors = [];
  const exp = testCase.expected || {};
  const lower = md.toLowerCase();
  for (const p of exp.mustCite || []) if (!result.cites.some((c) => c.path.includes(p)) && !md.includes(p)) errors.push(`case ${testCase.id}: does not cite ${p}`);
  for (const term of exp.mustMention || []) {
    const alts = Array.isArray(term) ? term : [term];
    if (!alts.some((a) => lower.includes(a.toLowerCase()))) errors.push(`case ${testCase.id}: does not mention ${alts.join(" or ")}`);
  }
  for (const term of exp.mustNotMention || []) if (lower.includes(term.toLowerCase())) errors.push(`case ${testCase.id}: mentions forbidden "${term}"`);
  if (exp.minOptions && result.optionCount < exp.minOptions) errors.push(`case ${testCase.id}: ${result.optionCount} options, expected >= ${exp.minOptions}`);
  if (exp.minRisks && result.riskCount < exp.minRisks) errors.push(`case ${testCase.id}: ${result.riskCount} risks, expected >= ${exp.minRisks}`);
  if (exp.status && result.status !== exp.status) errors.push(`case ${testCase.id}: status ${result.status}, expected ${exp.status}`);
  return errors;
}

export function loadCase(spec) {
  const [file, id] = spec.split("#");
  const found = (JSON.parse(readFileSync(file, "utf8")).cases || []).find((c) => c.id === id);
  if (!found) throw new Error(`case "${id}" not found in ${file}`);
  return found;
}

function main(argv) {
  const args = argv.slice(2);
  const take = (name) => { const i = args.indexOf(name); if (i < 0) return null; const v = args[i + 1]; args.splice(i, 2); return v; };
  const flag = (name) => { const i = args.indexOf(name); if (i < 0) return false; args.splice(i, 1); return true; };
  const json = flag("--json");
  const templateOnly = flag("--template-only");
  const repo = take("--repo");
  const status = take("--status");
  const bench = take("--bench");
  const caseSpec = take("--case");
  if (!args[0]) { console.error("usage: validate-adr.mjs <adr.md> [--repo dir] [--bench dir] [--status proposed] [--template-only] [--case cases.json#id] [--json]"); return 2; }
  const md = readFileSync(args[0], "utf8");
  const result = validateAdr(md, { repo: repo ? resolve(repo) : null, bench: bench ? resolve(bench) : null, status, templateOnly });
  const errors = [...result.errors];
  if (caseSpec) { try { errors.push(...gradeCase(md, result, loadCase(caseSpec))); } catch (e) { console.error(e.message); return 2; } }
  if (json) console.log(JSON.stringify({ ok: !errors.length, adr: result.number, status: result.status, options: result.optionCount, risks: result.riskCount, citations: result.cites.length, errors }, null, 2));
  else {
    for (const e of errors) console.log(`FAIL ${e}`);
    console.log(`${errors.length ? "INVALID" : "OK"}  ADR-${result.number ?? "????"} status=${result.status || "none"} options=${result.optionCount} risks=${result.riskCount} citations=${result.cites.length}${caseSpec ? ` case=${caseSpec.split("#")[1]}` : ""}`);
  }
  return errors.length ? 1 : 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv));

#!/usr/bin/env node
// Validate a code-review report (Markdown) against .claude/skills/code-review/output-format.md,
// and optionally grade it against a golden case from skills/code-review/tests/cases.json.
//
// Usage:
//   node validate-findings.mjs <report.md | -> [--repo <dir>] [--case <cases.json>#<case-id>] [--json]
//     --repo   <dir> is the AI-SDLC-frappe project root: every location path must exist under it and
//              the line must be within the (patched) file
//     --case   also check the golden case's expected verdict, required findings and forbidden findings
//     --json   print a JSON result instead of text
// Exit codes: 0 valid (and case passed), 1 invalid or case failed, 2 usage error.
// Frappe edition: also rejects a recommendation that tells the author to switch TO frappe.get_all,
// which does not check permissions (build/FRAPPE_FACTS.md section 6). Zero dependencies, Node 22.
import { readFileSync, existsSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const SEVERITIES = ["critical", "high", "medium", "low", "info"];
export const CATEGORIES = ["correctness", "design", "readability", "testing", "security", "performance", "standards", "docs"];
export const COLUMNS = ["id", "severity", "category", "location", "evidence", "recommendation"];
export const SECTIONS = ["Summary", "Findings", "Details", "Categories checked", "Verdict"];
export const VERDICTS = ["BLOCK", "NEEDS-DECISION", "APPROVE"];

/** Split a Markdown table row into trimmed cells, honouring `\|` escapes. */
export function splitRow(line) {
  const cells = [];
  let cur = "";
  const body = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  for (let i = 0; i < body.length; i++) {
    if (body[i] === "\\" && body[i + 1] === "|") { cur += "|"; i++; continue; }
    if (body[i] === "|") { cells.push(cur.trim()); cur = ""; continue; }
    cur += body[i];
  }
  cells.push(cur.trim());
  return cells;
}

/** Return { sections: Map(name -> text), order: [names] } for level-2 headings. */
export function splitSections(md) {
  const sections = new Map();
  const order = [];
  let current = null;
  for (const line of md.split(/\r?\n/)) {
    const m = /^##\s+(.+?)\s*$/.exec(line);
    if (m && !line.startsWith("###")) { current = m[1]; order.push(current); sections.set(current, []); continue; }
    if (current) sections.get(current).push(line);
  }
  return { sections: new Map([...sections].map(([k, v]) => [k, v.join("\n")])), order };
}

export function parseFindings(sectionText) {
  const lines = sectionText.split("\n").filter((l) => l.trim().startsWith("|"));
  if (lines.length < 2) return { header: null, rows: [] };
  const header = splitRow(lines[0]).map((c) => c.toLowerCase());
  const rows = lines.slice(2).map((l) => {
    const cells = splitRow(l);
    return Object.fromEntries(header.map((h, i) => [h, cells[i] ?? ""]));
  });
  return { header, rows };
}

const rank = (s) => SEVERITIES.indexOf(s);

export function expectedVerdict(findings) {
  if (findings.some((f) => rank(f.severity) >= 0 && rank(f.severity) <= 1)) return "BLOCK";
  if (findings.some((f) => f.severity === "medium")) return "NEEDS-DECISION";
  return "APPROVE";
}

export function validateReport(md, { repo = null, idPattern = /^CR-\d{3}$/ } = {}) {
  const errors = [];
  const { sections, order } = splitSections(md);
  const present = SECTIONS.filter((s) => sections.has(s));
  for (const s of SECTIONS) if (!sections.has(s)) errors.push(`missing section "## ${s}"`);
  const seen = order.filter((s) => SECTIONS.includes(s));
  if (present.length === SECTIONS.length && seen.join("|") !== SECTIONS.join("|")) errors.push(`sections out of order: ${seen.join(", ")}`);

  const { header, rows } = parseFindings(sections.get("Findings") || "");
  if (!header) errors.push("Findings section has no Markdown table");
  else if (header.join("|") !== COLUMNS.join("|")) errors.push(`findings table columns must be: ${COLUMNS.join(" | ")} (got: ${header.join(" | ")})`);

  const ids = new Set();
  let prevRank = -1;
  for (const [i, r] of rows.entries()) {
    const where = `row ${i + 1}${r.id ? ` (${r.id})` : ""}`;
    if (!idPattern.test(r.id || "")) errors.push(`${where}: id "${r.id}" does not match ${idPattern}`);
    if (ids.has(r.id)) errors.push(`${where}: duplicate id`);
    ids.add(r.id);
    if (!SEVERITIES.includes(r.severity)) errors.push(`${where}: severity "${r.severity}" not in ${SEVERITIES.join("|")}`);
    else {
      if (rank(r.severity) < prevRank) errors.push(`${where}: findings must be sorted by severity (critical first)`);
      prevRank = rank(r.severity);
    }
    if (!CATEGORIES.includes(r.category)) errors.push(`${where}: category "${r.category}" not in ${CATEGORIES.join("|")}`);
    const loc = /^`([^`:]+):(\d+)(?:-(\d+))?`/.exec(r.location || "");
    if (!loc) errors.push(`${where}: location must start with a backticked path:line, got "${r.location}"`);
    else if (repo) {
      const file = join(repo, loc[1]);
      if (!existsSync(file)) errors.push(`${where}: location file not found under --repo: ${loc[1]}`);
      else {
        const n = readFileSync(file, "utf8").split("\n").length;
        const last = Number(loc[3] || loc[2]);
        if (last > n) errors.push(`${where}: line ${last} is past the end of ${loc[1]} (${n} lines)`);
      }
    }
    if (!/`[^`]+`/.test(r.evidence || "") && !/^".+"$/.test(r.evidence || "")) errors.push(`${where}: evidence must quote code or output in backticks`);
    if (!/[A-Za-z0-9_.-]+\.md(#[\w-]+)?/.test(r.recommendation || "")) errors.push(`${where}: recommendation must cite a standard, e.g. frappe-coding-standards.md#4`);
    if (/\b(use|switch to|replace (it |this )?with)\s+`?frappe\.get_all\b/i.test(r.recommendation || "")) errors.push(`${where}: recommendation suggests frappe.get_all, which ignores permissions; use frappe.get_list`);
  }

  const details = sections.get("Details") || "";
  for (const id of ids) if (!new RegExp(`^###\\s+${id}\\b`, "m").test(details)) errors.push(`Details: missing "### ${id}"`);

  const checked = sections.get("Categories checked") || "";
  for (const c of CATEGORIES) {
    const line = checked.split("\n").find((l) => new RegExp(`^\\s*[-*]\\s*${c}\\s*:`).test(l));
    if (!line) { errors.push(`Categories checked: "${c}" not listed (write "${c}: no findings" if clean)`); continue; }
    const value = line.split(":").slice(1).join(":").trim();
    const catRows = rows.filter((r) => r.category === c);
    if (/^no findings\b/i.test(value)) {
      if (catRows.length) errors.push(`Categories checked: "${c}" says no findings but the table has ${catRows.map((r) => r.id).join(", ")}`);
    } else {
      const listed = value.match(/[A-Z]+-\d{3}/g) || [];
      for (const r of catRows) if (!listed.includes(r.id)) errors.push(`Categories checked: "${c}" does not list ${r.id}`);
      for (const id of listed) if (!ids.has(id)) errors.push(`Categories checked: "${c}" lists unknown id ${id}`);
    }
  }

  const verdictText = (sections.get("Verdict") || "").trim().split(/\s+/)[0] || "";
  if (!VERDICTS.includes(verdictText)) errors.push(`Verdict must start with one of ${VERDICTS.join("|")}, got "${verdictText}"`);
  else if (verdictText !== expectedVerdict(rows)) errors.push(`Verdict "${verdictText}" is inconsistent with severities (expected ${expectedVerdict(rows)})`);

  return { ok: errors.length === 0, errors, findings: rows, verdict: verdictText };
}

function matches(f, spec) {
  if (spec.category) {
    const cats = Array.isArray(spec.category) ? spec.category : [spec.category];
    if (!cats.includes(f.category)) return false;
  }
  if (spec.minSeverity && !(rank(f.severity) >= 0 && rank(f.severity) <= rank(spec.minSeverity))) return false;
  if (spec.location && !(f.location || "").includes(spec.location)) return false;
  if (spec.evidenceIncludes && !(f.evidence || "").toLowerCase().includes(spec.evidenceIncludes.toLowerCase())) return false;
  return true;
}

/** Grade a validated report against one golden case ({ expected: { verdict, findings, forbidden, maxSeverity } }). */
export function gradeCase(result, testCase) {
  const errors = [];
  const exp = testCase.expected || {};
  if (exp.verdict && result.verdict !== exp.verdict) errors.push(`case ${testCase.id}: verdict ${result.verdict}, expected ${exp.verdict}`);
  for (const spec of exp.findings || []) {
    if (!result.findings.some((f) => matches(f, spec))) errors.push(`case ${testCase.id}: no finding matches ${JSON.stringify(spec)}`);
  }
  for (const spec of exp.forbidden || []) {
    const hit = result.findings.find((f) => matches(f, spec));
    if (hit) errors.push(`case ${testCase.id}: forbidden finding present ${hit.id} matches ${JSON.stringify(spec)}`);
  }
  if (exp.maxSeverity) {
    const worse = result.findings.filter((f) => rank(f.severity) < rank(exp.maxSeverity));
    if (worse.length) errors.push(`case ${testCase.id}: findings above ${exp.maxSeverity}: ${worse.map((f) => f.id).join(", ")}`);
  }
  return errors;
}

export function loadCase(spec) {
  const [file, id] = spec.split("#");
  const data = JSON.parse(readFileSync(file, "utf8"));
  const found = (data.cases || []).find((c) => c.id === id);
  if (!found) throw new Error(`case "${id}" not found in ${file}`);
  return found;
}

function main(argv) {
  const args = argv.slice(2);
  const opt = (name) => { const i = args.indexOf(name); if (i < 0) return null; const v = args[i + 1]; args.splice(i, 2); return v; };
  const json = args.includes("--json");
  if (json) args.splice(args.indexOf("--json"), 1);
  const repo = opt("--repo");
  const caseSpec = opt("--case");
  const input = args[0];
  if (!input) { console.error("usage: validate-findings.mjs <report.md|-> [--repo dir] [--case cases.json#id] [--json]"); return 2; }
  const md = readFileSync(input === "-" ? 0 : input, "utf8");
  const result = validateReport(md, { repo: repo ? resolve(repo) : null });
  const errors = [...result.errors];
  if (caseSpec) {
    try { errors.push(...gradeCase(result, loadCase(caseSpec))); } catch (e) { console.error(e.message); return 2; }
  }
  const counts = Object.fromEntries(SEVERITIES.map((s) => [s, result.findings.filter((f) => f.severity === s).length]));
  if (json) console.log(JSON.stringify({ ok: errors.length === 0, verdict: result.verdict, counts, errors }, null, 2));
  else {
    for (const e of errors) console.log(`FAIL ${e}`);
    console.log(`${errors.length ? "INVALID" : "OK"}  ${result.findings.length} findings ${JSON.stringify(counts)} verdict=${result.verdict || "none"}${caseSpec ? ` case=${caseSpec.split("#")[1]}` : ""}`);
  }
  return errors.length ? 1 : 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv));

#!/usr/bin/env node
// Validate a test plan produced by the test-strategy skill against TEST_PLAN_TEMPLATE.md,
// and optionally grade it against a golden case from skills/test-strategy/tests/cases.json.
//
// Usage:
//   node validate-test-plan.mjs <plan.md> [--repo <dir>] [--bench <dir>] [--case <cases.json>#<id>] [--json]
//     --repo   <dir> is the AI-SDLC-frappe project root: every `existing` test must exist in the app's
//              test_*.py files, every `new`/`new-failing` test must not, and cited path:line must resolve
//     --bench  resolve cited `apps/...` paths (Frappe source) against this bench directory
//     --case   also check the case's requiredCategories / mustReferenceTests / mustMention / minCases / minFindings
// Exit codes: 0 valid, 1 invalid or case failed, 2 usage error. Zero dependencies, Node 22.
import { readFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const CATEGORIES = ["unit", "integration", "api", "negative", "edge", "performance", "security", "regression"];
export const SECTIONS = ["Scope", "Risks and defects found while planning", "Test cases", "Coverage matrix", "Test data", "Exit criteria"];
export const CASE_COLUMNS = ["id", "category", "tool", "test", "scenario", "expected", "status"];
export const FINDING_COLUMNS = ["id", "severity", "category", "location", "evidence", "recommendation"];
export const STATUSES = ["existing", "new", "new-failing"];
export const SEVERITIES = ["critical", "high", "medium", "low", "info"];
export const APP_TESTS = "sample-app/spice_lite/spice_lite";
const TOOLS = /frappetestcase|unittest|query counter|assertquerycount|set_user|call\(\)|mock/i;
const TEST_NAME = /^`?(Test\w+)#(test_\w+)`?$/;
const PATH_LINE = /`((?:[\w.-]+\/)+[\w.-]+\.(?:py|json|md|txt|mjs|ya?ml)):(\d+)(?:-(\d+))?`/g;

export function splitRow(line) {
  const out = [];
  let cur = "";
  const body = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  for (let i = 0; i < body.length; i++) {
    if (body[i] === "\\" && body[i + 1] === "|") { cur += "|"; i++; continue; }
    if (body[i] === "|") { out.push(cur.trim()); cur = ""; continue; }
    cur += body[i];
  }
  out.push(cur.trim());
  return out;
}

function firstTable(text) {
  const lines = text.split("\n");
  const start = lines.findIndex((l) => l.trim().startsWith("|"));
  if (start < 0) return null;
  const block = [];
  for (let i = start; i < lines.length && lines[i].trim().startsWith("|"); i++) block.push(lines[i]);
  if (block.length < 2) return null;
  const header = splitRow(block[0]).map((c) => c.toLowerCase());
  return { header, rows: block.slice(2).map((l) => Object.fromEntries(splitRow(l).map((c, i) => [header[i], c]))) };
}

export function sections(md) {
  const map = new Map();
  const order = [];
  let cur = null;
  for (const line of md.split(/\r?\n/)) {
    const m = /^## (?!#)(.+?)\s*$/.exec(line);
    if (m) { cur = m[1]; order.push(cur); map.set(cur, []); continue; }
    if (cur) map.get(cur).push(line);
  }
  return { order, text: new Map([...map].map(([k, v]) => [k, v.join("\n")])) };
}

function listTestFiles(dir) {
  const out = [];
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    if (name === "__pycache__" || name === "node_modules") continue;
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...listTestFiles(p));
    else if (/^test_.*\.py$/.test(name)) out.push(p);
  }
  return out;
}

/** True when a file under the app defines `class <cls>(` and, in that file, `def <method>(`. */
export function testExists(repo, cls, method) {
  return listTestFiles(join(repo, APP_TESTS)).some((f) => {
    const src = readFileSync(f, "utf8");
    return new RegExp(`^class\\s+${cls}\\s*\\(`, "m").test(src) && new RegExp(`^\\s+def\\s+${method}\\s*\\(`, "m").test(src);
  });
}

export function validatePlan(md, { repo = null, bench = null } = {}) {
  const errors = [];
  if (!/^# Test plan: .+/.test(md.split("\n")[0] || "")) errors.push('first line must be "# Test plan: <change>"');
  const { order, text } = sections(md);
  const seen = order.filter((s) => SECTIONS.includes(s));
  for (const s of SECTIONS) if (!text.has(s)) errors.push(`missing section "## ${s}"`);
  if (seen.length === SECTIONS.length && seen.join("|") !== SECTIONS.join("|")) errors.push(`sections out of order: ${seen.join(", ")}`);
  if (!/^### Change surface \(evidence\)/m.test(text.get("Scope") || "")) errors.push('Scope needs "### Change surface (evidence)"');
  if (!/^### Existing coverage/m.test(text.get("Scope") || "")) errors.push('Scope needs "### Existing coverage"');

  const findings = firstTable(text.get("Risks and defects found while planning") || "");
  const findingRows = findings ? findings.rows : [];
  if (findings) {
    if (findings.header.join("|") !== FINDING_COLUMNS.join("|")) errors.push(`findings table columns must be: ${FINDING_COLUMNS.join(" | ")}`);
    for (const f of findingRows) {
      if (!/^TS-\d{3}$/.test(f.id || "")) errors.push(`finding "${f.id}": id must be TS-NNN`);
      if (!SEVERITIES.includes(f.severity)) errors.push(`finding ${f.id}: severity "${f.severity}" invalid`);
      if (!/^`[^`]+:\d+/.test(f.location || "")) errors.push(`finding ${f.id}: location must be a backticked path:line`);
      if (!/`[^`]+`/.test(f.evidence || "")) errors.push(`finding ${f.id}: evidence must quote code or output in backticks`);
    }
  } else if (!/no (risks|defects)/i.test(text.get("Risks and defects found while planning") || "")) {
    errors.push('Risks section needs a findings table or the sentence "No risks or defects found."');
  }

  const tc = firstTable(text.get("Test cases") || "");
  const cases = tc ? tc.rows : [];
  if (!tc || tc.header.join("|") !== CASE_COLUMNS.join("|")) errors.push(`test case table columns must be: ${CASE_COLUMNS.join(" | ")}`);
  const ids = new Set();
  for (const c of cases) {
    const where = `test case ${c.id || "?"}`;
    if (!/^TC-\d{2,3}$/.test(c.id || "")) errors.push(`${where}: id must be TC-NN`);
    if (ids.has(c.id)) errors.push(`${where}: duplicate id`);
    ids.add(c.id);
    if (!CATEGORIES.includes(c.category)) errors.push(`${where}: category "${c.category}" not in ${CATEGORIES.join("|")}`);
    if (!TOOLS.test(c.tool || "")) errors.push(`${where}: tool "${c.tool}" must name unittest, FrappeTestCase, call(), a query counter, frappe.set_user or unittest.mock`);
    const name = TEST_NAME.exec(c.test || "");
    if (!name) errors.push(`${where}: test "${c.test}" must be \`TestSomething#test_behaviour\``);
    if (!STATUSES.includes(c.status)) errors.push(`${where}: status "${c.status}" not in ${STATUSES.join("|")}`);
    if (!c.scenario || !c.expected) errors.push(`${where}: scenario and expected must be filled`);
    if (repo && name && STATUSES.includes(c.status)) {
      const exists = testExists(repo, name[1], name[2]);
      if (c.status === "existing" && !exists) errors.push(`${where}: marked existing but ${name[1]}#${name[2]} is not in ${APP_TESTS}`);
      if (c.status !== "existing" && exists) errors.push(`${where}: marked ${c.status} but ${name[1]}#${name[2]} already exists`);
    }
  }

  const cov = firstTable(text.get("Coverage matrix") || "");
  if (!cov) errors.push("Coverage matrix needs a table");
  else {
    for (const cat of CATEGORIES) {
      const row = cov.rows.find((r) => r.category === cat);
      if (!row) { errors.push(`Coverage matrix: category "${cat}" missing`); continue; }
      const listed = (row.cases || "").match(/TC-\d{2,3}/g) || [];
      const actual = cases.filter((c) => c.category === cat).map((c) => c.id);
      if (!listed.length && !/^N\/A:\s*\S/.test(row.cases || "")) errors.push(`Coverage matrix: "${cat}" needs case ids or "N/A: reason"`);
      for (const id of actual) if (!listed.includes(id)) errors.push(`Coverage matrix: "${cat}" does not list ${id}`);
      for (const id of listed) if (!actual.includes(id)) errors.push(`Coverage matrix: "${cat}" lists ${id}, which is not a ${cat} case`);
    }
  }

  const cites = [...md.matchAll(PATH_LINE)].map((m) => ({ path: m[1], from: Number(m[2]), to: Number(m[3] || m[2]) }));
  for (const c of cites) {
    const base = c.path.startsWith("apps/") ? bench : repo;
    if (!base) continue;
    const file = join(base, c.path);
    if (!existsSync(file)) { errors.push(`cited file not found: ${c.path}`); continue; }
    const n = readFileSync(file, "utf8").split("\n").length;
    if (c.to > n || c.from > c.to) errors.push(`cited line ${c.path}:${c.from}${c.to !== c.from ? `-${c.to}` : ""} is outside the file (${n} lines)`);
  }
  if (!/run-tests/.test(text.get("Exit criteria") || "")) errors.push("Exit criteria must include the `bench --site ... run-tests` command");
  return { ok: errors.length === 0, errors, cases, findings: findingRows, cites };
}

export function gradeCase(md, result, testCase) {
  const errors = [];
  const exp = testCase.expected || {};
  const lower = md.toLowerCase();
  for (const cat of exp.requiredCategories || []) if (!result.cases.some((c) => c.category === cat)) errors.push(`case ${testCase.id}: no ${cat} test case`);
  for (const t of exp.mustReferenceTests || []) if (!md.includes(t)) errors.push(`case ${testCase.id}: does not reference ${t}`);
  for (const term of exp.mustMention || []) {
    const alts = Array.isArray(term) ? term : [term];
    if (!alts.some((a) => lower.includes(a.toLowerCase()))) errors.push(`case ${testCase.id}: does not mention ${alts.join(" or ")}`);
  }
  if (exp.minCases && result.cases.length < exp.minCases) errors.push(`case ${testCase.id}: ${result.cases.length} test cases, expected >= ${exp.minCases}`);
  if (exp.minFindings && result.findings.length < exp.minFindings) errors.push(`case ${testCase.id}: ${result.findings.length} findings, expected >= ${exp.minFindings}`);
  return errors;
}

export function loadCase(spec) {
  const [file, id] = spec.split("#");
  const found = (JSON.parse(readFileSync(file, "utf8")).cases || []).find((c) => c.id === id);
  if (!found) throw new Error(`case "${id}" not found in ${file}`);
  return found;
}

function main(argv) {
  const args = argv.slice(2);
  const take = (n) => { const i = args.indexOf(n); if (i < 0) return null; const v = args[i + 1]; args.splice(i, 2); return v; };
  const json = args.includes("--json");
  if (json) args.splice(args.indexOf("--json"), 1);
  const repo = take("--repo");
  const bench = take("--bench");
  const caseSpec = take("--case");
  if (!args[0]) { console.error("usage: validate-test-plan.mjs <plan.md> [--repo dir] [--bench dir] [--case cases.json#id] [--json]"); return 2; }
  const md = readFileSync(args[0], "utf8");
  const result = validatePlan(md, { repo: repo ? resolve(repo) : null, bench: bench ? resolve(bench) : null });
  const errors = [...result.errors];
  if (caseSpec) { try { errors.push(...gradeCase(md, result, loadCase(caseSpec))); } catch (e) { console.error(e.message); return 2; } }
  const byCat = Object.fromEntries(CATEGORIES.map((c) => [c, result.cases.filter((x) => x.category === c).length]));
  const byStatus = Object.fromEntries(STATUSES.map((s) => [s, result.cases.filter((x) => x.status === s).length]));
  if (json) console.log(JSON.stringify({ ok: !errors.length, cases: result.cases.length, byCategory: byCat, byStatus, findings: result.findings.length, errors }, null, 2));
  else {
    for (const e of errors) console.log(`FAIL ${e}`);
    console.log(`${errors.length ? "INVALID" : "OK"}  ${result.cases.length} cases ${JSON.stringify(byCat)} ${JSON.stringify(byStatus)} findings=${result.findings.length}${caseSpec ? ` case=${caseSpec.split("#")[1]}` : ""}`);
  }
  return errors.length ? 1 : 0;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exit(main(process.argv));

